import Link from 'next/link';import {ArrowUpRight} from 'lucide-react';import {products,values,mission,vision,team,socials} from '@/data/site';import {ConceptVisual,EmailCapture} from '@/components/shared';
export function About(){return <><PageHero eyebrow="ABOUT QORVAYN" title="Meaningful technology for the future." text="QORVAYN is a growing technology company founded on 10 March 2026, building intelligent digital products around real human needs."/><section className="section"><div className="container grid-2"><div className="card"><div className="label">Mission</div><p className="quote">“{mission}”</p></div><div className="card"><div className="label">Vision</div><p className="quote">“{vision}”</p></div></div></section><section className="section"><div className="container split"><div><div className="eyebrow">OUR STORY</div><h2>A simple ambition, built for the long term.</h2><p>QORVAYN began on 10 March 2026 with a simple ambition: to build meaningful technology for the future. Founded by Ryan Zannah, QORVAYN is growing into a technology ecosystem focused on intelligent software, creative digital experiences, and products designed around real human needs. QORVAYN currently follows a remote-first approach. While the team primarily works remotely, members occasionally meet in person at a private location to collaborate, plan, and work together.</p></div><div className="timeline"><div><strong>10 MARCH 2026</strong><h3>Founded</h3></div><div><strong>TODAY</strong><h3>Building an expanding technology ecosystem</h3></div><div><strong>FUTURE</strong><h3>More products in development</h3></div></div></div></section><section className="section"><div className="container"><div className="card"><div className="eyebrow">OPERATING MODEL</div><h2>Bangladesh · Remote-first</h2><p>QORVAYN operates remotely, with occasional in-person collaboration.</p></div></div></section><Values/></>}
export function Values(){return <section className="section values"><div className="container"><div className="eyebrow">CORE VALUES</div><h2>Built with intention.</h2><div className="grid-3">{values.map(([n,t],i)=><div className="card" key={n}><div className="num">0{i+1}</div><h3>{n}</h3><p>{t}</p></div>)}</div></div></section>}
export function Products(){return <><PageHero eyebrow="QORVAYN ECOSYSTEM" title="Different products. One human-centered direction." text="Our products share a common belief: technology should be intelligent, accessible, and designed around real human needs."/><section className="section"><div className="container grid-3">{products.map((p,i)=><Link className="card" href={'/products/'+p.slug} key={p.slug}><div className="card-top"><span className="num">0{i+1}</span><span className="arrow">↗</span></div><h2 style={{fontSize:'2.3rem'}}>{p.name}</h2><span className="label">Product vision</span><p>{p.description}</p><span className="btn btn-ghost">Explore {p.name}</span></Link>)}</div></section><section className="section"><div className="container"><div className="section-head"><div><div className="eyebrow">IN DEVELOPMENT</div><h2>More to come.</h2></div><p>More products are currently in development.</p></div><div className="grid-3">{['Future product','Currently in development','More to come'].map(t=><div className="card" key={t}><div className="orb" style={{height:130,opacity:.5}}/><h3>{t}</h3></div>)}</div></div></section></>}
export function Team(){return <><PageHero eyebrow="THE PEOPLE BEHIND QORVAYN" title="A team building toward the future." text="QORVAYN is a remote-first team building intelligent digital products and creative experiences."/><section className="section"><div className="container"><div className="grid-2">{team.map(([initials,name,role])=><div className="card team-card" key={name}><div className="avatar">{initials}</div><div><h3>{name}</h3><p>{role}</p></div></div>)}</div><p className="meta" style={{marginTop:24}}>Team titles are displayed based on current responsibilities and team agreement.</p></div></section></>}
export function Contact(){return <><PageHero eyebrow="CONTACT QORVAYN" title="Let’s build something meaningful." text="For questions, collaboration, and general inquiries, contact QORVAYN."/><section className="section"><div className="container split"><div><div className="card"><div className="label">Email</div><h2 style={{fontSize:'2rem'}}><a href="mailto:theqorvayn@gmail.com">theqorvayn@gmail.com</a></h2><p>Bangladesh · Remote-first</p></div><div className="card" style={{marginTop:16}}><div className="label">Social</div>{socials.map(([n,u])=><a style={{display:'block',margin:'12px 0'}} href={u} target="_blank" rel="noreferrer" key={n}>{n} ↗</a>)}</div></div><div><div className="notice">This contact form interface is ready for email-service integration.</div><form className="form" style={{marginTop:16}} action="/contact/thank-you"><div className="form-row"><input name="name" placeholder="Name" required/><input name="email" type="email" placeholder="Email" required/></div><input name="subject" placeholder="Subject (optional)"/><textarea name="message" placeholder="Message" required/><button className="btn btn-primary" type="submit">Send message <ArrowUpRight size={16}/></button></form></div></div></section></>}
export function ThankYou(){return <><PageHero eyebrow="MESSAGE RECEIVED" title="Thanks — we’ve received your message." text="We’ll reply as soon as we can."/><section className="section"><div className="container card"><p>For a direct inquiry, email <a href="mailto:theqorvayn@gmail.com">theqorvayn@gmail.com</a>.</p><div className="hero-actions"><Link className="btn btn-primary" href="/products">Explore our products</Link><Link className="btn btn-ghost" href="/">Return home</Link></div></div></section></>}
export function Future(){return <><PageHero eyebrow="WHAT’S NEXT" title="The ecosystem is growing." text="More products are currently in development."/><section className="section"><div className="container split"><div><p className="quote">“QORVAYN is building toward a future where intelligent software, creative tools, and digital experiences work together to empower people.”</p></div><ConceptVisual variant="future"/></div></section><section className="section"><div className="container"><div className="grid-3">{['Future product','Currently in development','More to come'].map((t,i)=><div className="card" key={t}><div className="num">0{i+1}</div><h3>{t}</h3><p>Exploring what comes next, with care and intention.</p></div>)}</div><div className="card" style={{marginTop:16,maxWidth:560}}><div className="eyebrow">STAY CLOSE</div><h2 style={{fontSize:'2.4rem'}}>Follow what comes next.</h2><EmailCapture button="Get future updates"/></div></div></section></>}
export function Legal({kind}:{kind:'Privacy'|'Terms'}){const sections=kind==='Privacy'?['Introduction','Information we collect','How we use information','Data sharing','Your rights','Contact']:['Acceptance of Terms','Use of the Site','Intellectual Property','Disclaimers','Limitation of Liability','Changes to Terms','Contact'];return <><PageHero eyebrow="LEGAL" title={kind} text={kind==='Privacy'?'This page explains how QORVAYN may handle information collected through this website.':'These terms are a readable template for the QORVAYN website.'}/><section className="section"><div className="container legal"><div className="notice">This legal content is a draft template and must be reviewed and finalized before publication.</div>{sections.map(s=><div key={s}><h2>{s}</h2><p>This section contains neutral placeholder copy for the future finalized {kind.toLowerCase()} content of QORVAYN. It should be reviewed and replaced with appropriate wording before publication.</p></div>)}<p>Contact: <a href="mailto:theqorvayn@gmail.com">theqorvayn@gmail.com</a></p></div></section></>}
export function PageHero({eyebrow,title,text}:{eyebrow:string,title:string,text:string}){return <section className="container page-hero"><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{text}</p></section>}
